const field = (rhs, initial, exact = '') => ({rhs, initial, exact});
const base = {dimension: 1, N: 128, Lx: 2 * Math.PI, Ly: 2 * Math.PI, T: 2, dt: .02, frames: 61, parameters: '', boundary: 'periodic'};
export const PRESETS = [
  {id: 'heat', label: 'Heat diffusion', area: 'Transport', description: 'Watch short wavelengths decay faster. An exact periodic solution provides a direct accuracy benchmark.', config: {...base, title: 'Heat diffusion', parameters: 'nu = 0.25', fields: [field('nu*lap(u)', 'sin(x) + 0.25*cos(2*x)', 'exp(-nu*t)*sin(x) + 0.25*exp(-4*nu*t)*cos(2*x)')]}},
  {id: 'burgers', label: 'Viscous Burgers', area: 'Nonlinear waves', description: 'Compare nonlinear steepening with viscous smoothing. Reduce nu, then check both spatial and temporal resolution.', config: {...base, title: 'Viscous Burgers', N: 256, dt: .01, parameters: 'nu = 0.025', fields: [field('nu*lap(u) - 0.5*Dx(u^2, 1)', '0.7*sin(x)')]}},
  {id: 'kdv', label: 'KdV pulse', area: 'Dispersive waves', description: 'A localized pulse travels in a periodic domain. Watch its shape and mean; periodic copies can interact over longer times.', config: {...base, title: 'KdV pulse', N: 256, Lx: 40, T: 4, dt: .01, fields: [field('-Dx(u,3) - 6*u*Dx(u,1)', '0.5*(1-tanh(x/2)^2)')]}},
  {id: 'ks', label: 'Kuramoto–Sivashinsky', area: 'Pattern dynamics', description: 'Long wavelengths grow while fourth-order dissipation suppresses small scales. Explore the onset of complex dynamics.', config: {...base, title: 'Kuramoto–Sivashinsky', N: 256, Lx: 32 * Math.PI, T: 40, dt: .1, fields: [field('-Dx(u,2) - Dx(u,4) - 0.5*Dx(u^2,1)', 'cos(2*pi*x/Lx)*(1+0.1*sin(4*pi*x/Lx))')]}},
  {id: 'wave', label: 'Wave equation', area: 'Coupled fields', description: 'Write a second-order time equation as u_t = v and v_t = c² u_xx. Coupling is explicit: refine the time step.', config: {...base, title: 'Wave equation as a system', T: 6, dt: .005, parameters: 'c = 1', fields: [field('v', 'sin(x)', 'cos(c*t)*sin(x)'), field('c^2*lap(u)', '0', '-c*sin(c*t)*sin(x)')]}},
  {id: 'allen', label: 'Allen–Cahn · 2D', area: 'Phase separation', description: 'Observe two phases form and interfaces move. This dimensionless example illustrates interfacial dynamics; it is not a calibrated material model.', config: {...base, title: 'Allen–Cahn phase separation', dimension: 2, N: 64, Lx: 10, Ly: 10, T: 12, dt: .05, parameters: 'epsilon = 0.08', fields: [field('epsilon*lap(u) + u - u^3', '0.3*cos(2*pi*x/Lx)+0.2*sin(4*pi*y/Ly)+0.1*sin(2*pi*(x/Lx+y/Ly))')]}},
  {id: 'gray', label: 'Gray–Scott · 2D', area: 'Reaction–diffusion', description: 'Two species diffuse and react. Change feed and removal rates to explore pattern sensitivity, then export both concentration fields.', config: {...base, title: 'Gray–Scott reaction–diffusion', dimension: 2, N: 64, Lx: 32, Ly: 32, T: 800, dt: 1, parameters: 'Du = 0.16; Dv = 0.08; F = 0.035; k = 0.065', fields: [field('Du*lap(u) - u*v^2 + F*(1-u)', '1-0.5*exp(-(x^2+y^2)/16)'), field('Dv*lap(v) + u*v^2 - (F+k)*v', '0.25*exp(-(x^2+y^2)/16)*(1+0.1*cos(x)*cos(y))')]}},
  {id: 'cahn', label: 'Cahn–Hilliard · 2D', area: 'Conserved phases', description: 'A fourth-order model of phase separation. Compare the evolving pattern with its spatial mean; conservation alone does not establish accuracy.', config: {...base, title: 'Cahn–Hilliard phase separation', dimension: 2, N: 64, Lx: 16, Ly: 16, T: 12, dt: .02, parameters: 'epsilon = 0.5', fields: [field('-epsilon^2*biharm(u) - lap(u) + lap(u^3)', '0.1*cos(2*pi*x/Lx)+0.08*sin(4*pi*y/Ly)+0.03*cos(6*pi*(x/Lx+y/Ly))')]}},
  {id: 'advection2d', label: 'Advection–diffusion · 2D', area: 'Transport benchmark', description: 'A periodic pattern is transported and diffused in two directions. Check the numerical field against a known exact solution.', config: {...base, title: 'Two-dimensional transport benchmark', dimension: 2, N: 64, T: 3, dt: .05, parameters: 'nu = 0.1; cx = 1; cy = 0.5', fields: [field('nu*lap(u)-cx*Dx(u,1)-cy*Dy(u,1)', 'cos(x)+0.5*sin(y)', 'exp(-nu*t)*(cos(x-cx*t)+0.5*sin(y-cy*t))')]}},
];
export const presetConfig = id => structuredClone((PRESETS.find(p => p.id === id) || PRESETS[0]).config);
